// Generated by Codex, 12 October 2026. Simulation-only gate shared by future channels.
export function assessPlan(result) {
 const {config:c,optimized:o}=result;
 const reasons=[];
 if(o.rows.some(r=>r.stored < c.battery*c.reserve/100-1e-8)) reasons.push('Reserva mínima incumplida');
 if(o.peak > c.gridLimit+1e-8) reasons.push('Potencia de red superior al límite configurado');
 if(o.unmet > 1e-8) reasons.push('Demanda de vehículos incompleta');
 return {status:reasons.length?'blocked':'simulation-only',reasons,realExecutionAllowed:false};
}
export function respondToRequest(question,result,explain) {
 const guard=assessPlan(result);
 if(/enciende|apaga|ejecuta|activa|desactiva|ignora|elimina.*reserva|sin.*reserva/i.test(question))
  return 'CEREBRO solo simula y recomienda. No ejecuta órdenes sobre equipos. La reserva y los límites de seguridad no se pueden omitir por una petición al asistente.';
 return explain(question,result)+(guard.status==='blocked'?' Plan bloqueado para aprobación: '+guard.reasons.join('; ')+'.':'');
}
